#include <stddef.h>
typedef struct { int data[32]; size_t n; } IStack;
typedef struct { double data[32]; size_t n; } DStack;
static int si_push(IStack *s, int v) { if (s->n == 32) return -1; s->data[s->n++] = v; return 0; }
static int sd_push(DStack *s, double v) { if (s->n == 32) return -1; s->data[s->n++] = v; return 0; }
static int si_pop(IStack *s, int *out) { if (s->n == 0) return -1; *out = s->data[--s->n]; return 0; }
static int sd_pop(DStack *s, double *out) { if (s->n == 0) return -1; *out = s->data[--s->n]; return 0; }

